export async function createScene(engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.03, 0.01, 0.09);
  scene.useRightHandedSystem = true;

  const camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(70), 20, BABYLON.Vector3.Zero(), scene);
  camera.attachControl(canvas, true);

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.8;

  const obstacles = [];

  const R = 2;
  const sphere = BABYLON.MeshBuilder.CreateSphere("sphere", { diameter: 2 * R }, scene);
  sphere.position.set(0, 0, 0);
  sphere.material = new BABYLON.StandardMaterial("matSphere", scene);
  sphere.material.diffuseColor = new BABYLON.Color3(0.2, 0.4, 1);
  obstacles.push({ mesh: sphere, type: "sphere", radius: R });

  const boxSize = 3;
  const box = BABYLON.MeshBuilder.CreateBox("box", { size: boxSize }, scene);
  box.position.set(5, 0, 2.5);
  box.material = new BABYLON.StandardMaterial("matBox", scene);
  box.material.diffuseColor = new BABYLON.Color3(1, 0.3, 0.3);
  obstacles.push({ mesh: box, type: "box", size: boxSize / 2 }); // size는 반길이(half size)

  const torusKnot = BABYLON.MeshBuilder.CreateTorusKnot("torusKnot", { radius: R, tube: 0.5, radialSegments: 128, tubularSegments: 64, p: 2, q: 3 });
  torusKnot.position.set(3, 2, 0);
  torusKnot.material = new BABYLON.StandardMaterial("matBox", scene);
  torusKnot.material.diffuseColor = new BABYLON.Color3(0.3, 1, 0.36);
  obstacles.push({ mesh: torusKnot, type: "torusKnot", size: R });

  const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene);
  dpp.fxaaEnabled = true;
  dpp.imageProcessingEnabled = false;
  dpp.glowLayerEnabled = true;

  const U = 2;
  const Gamma = 15;
  const K = -U * R * R;

  const numParticles = 100;
  const trailLength = 60;

  const particles = [];

  function getVelocityField(x, y) {
    const r2 = x * x + y * y;
    let u = U,
      v = 0;

    if (r2 > R * R * 0.8) {
      u += ((K / (2 * Math.PI)) * (x * x - y * y)) / Math.pow(r2, 2);
      v += ((K / (2 * Math.PI)) * (2 * x * y)) / Math.pow(r2, 2);
      u += ((-Gamma / (2 * Math.PI)) * y) / r2;
      v += ((Gamma / (2 * Math.PI)) * x) / r2;
    }

    return new BABYLON.Vector2(u, v);
  }

  function createParticle(i) {
    const x = -10 + Math.random() * 2;
    const y = Math.random() * 10 - 5;
    const z = Math.random() * 10 - 5;

    const head = BABYLON.MeshBuilder.CreateSphere("head" + i, { diameter: 0.1 }, scene);
    head.position.set(x, y, z);

    const mat = new BABYLON.StandardMaterial("pMat" + i, scene);
    mat.emissiveColor = new BABYLON.Color3(1, 1, 0);
    mat.disableLighting = true;
    head.material = mat;

    // trailPoints: 고정 길이 배열 (초기값 모두 현재 위치 복제)
    const trailPoints = new Array(trailLength);
    for (let j = 0; j < trailLength; j++) {
      trailPoints[j] = head.position.clone();
    }

    // 처음에 선분 생성 (updatable)
    const lines = BABYLON.MeshBuilder.CreateLines(
      "trail" + i,
      {
        points: trailPoints,
        updatable: true,
      },
      scene
    );
    lines.color = new BABYLON.Color3(1, 1, 0);

    // trail에서 현재 쓸 인덱스 (circular buffer)
    let trailIndex = 0;

    return { head, mat, lines, trailPoints, trailIndex };
  }

  for (let i = 0; i < numParticles; i++) {
    particles.push(createParticle(i));
  }

  // 장애물과 거리 계산 함수들
  function distanceToSphere(p, sphere) {
    return p.subtract(sphere.mesh.position).length() - sphere.radius;
  }

  function surfaceNormalToSphere(p, sphere) {
    return p.subtract(sphere.mesh.position).normalize();
  }

  function distanceToBox(p, box) {
    const local = p.subtract(box.mesh.position);
    const d = new BABYLON.Vector3(
      Math.max(Math.abs(local.x) - box.size, 0),
      Math.max(Math.abs(local.y) - box.size, 0),
      Math.max(Math.abs(local.z) - box.size, 0)
    );
    return d.length();
  }

  function isPointInsideMesh(mesh, point) {
    const rayDirection = new BABYLON.Vector3(1, 0, 0); // +X 방향 레이
    const ray = new BABYLON.Ray(point, rayDirection, 1000);
    const pickInfos = mesh.intersects(ray, true);

    if (!pickInfos || pickInfos.length === 0) return false;

    // 레이와 mesh가 교차하는 점 개수
    const hitCount = pickInfos.length;

    // 홀수면 내부, 짝수면 외부
    return hitCount % 2 === 1;
  }

  function getClosestPointAndNormal(mesh, point) {
    const dir = mesh.position.subtract(point).normalize();
    const ray = new BABYLON.Ray(point, dir, 100);

    const pickInfo = scene.pickWithRay(ray, (m) => m === mesh);

    if (pickInfo.hit && pickInfo.pickedPoint) {
      const closestPoint = pickInfo.pickedPoint;
      const normal = point.subtract(closestPoint).normalize();
      const distance = BABYLON.Vector3.Distance(point, closestPoint);
      return { distance, normal };
    }
    return { distance: Number.MAX_VALUE, normal: null };
  }

  function surfaceNormalToBox(p, box) {
    const local = p.subtract(box.mesh.position);
    const halfSize = box.size;

    const dx = Math.abs(local.x) - halfSize;
    const dy = Math.abs(local.y) - halfSize;
    const dz = Math.abs(local.z) - halfSize;

    const maxD = Math.max(dx, dy, dz);

    if (maxD === dx && dx > 0) return new BABYLON.Vector3(Math.sign(local.x), 0, 0);
    if (maxD === dy && dy > 0) return new BABYLON.Vector3(0, Math.sign(local.y), 0);
    if (maxD === dz && dz > 0) return new BABYLON.Vector3(0, 0, Math.sign(local.z));

    return new BABYLON.Vector3(1, 0, 0);
  }

  scene.onBeforeRenderObservable.add(() => {
    const dt = engine.getDeltaTime() / 1000;

    particles.forEach((p) => {
      const { head, mat, lines, trailPoints } = p;

      // trailIndex를 꺼내서 업데이트
      let trailIndex = p.trailIndex;

      // 2D 유동장 속도 (x,y 평면만)
      const v2d = getVelocityField(head.position.x, head.position.y);
      let velocity = new BABYLON.Vector3(v2d.x, -v2d.y, 0);
      // let velocity = new BABYLON.Vector3(v2d.x, 0, 0);

      // 장애물 회피 벡터 보정
      let minDist = 1e6;
      let avoidance = new BABYLON.Vector3(0, 0, 0);

      obstacles.forEach((ob) => {
        let dist, normal;

        if (ob.type === "sphere") {
          dist = distanceToSphere(head.position, ob);
          normal = surfaceNormalToSphere(head.position, ob);
        } else if (ob.type === "box") {
          dist = distanceToBox(head.position, ob);
          normal = surfaceNormalToBox(head.position, ob);
        } else {
          const inside = isPointInsideMesh(ob.mesh, head.position);
          if (inside) {
            const res = getClosestPointAndNormal(ob.mesh, head.position);
            dist = res.distance;
            normal = res.normal;

            if (normal) {
              const pushOutForce = normal.scale(5);
              velocity = velocity.add(pushOutForce.scale(dt));
            }
          } else {
            const res = getClosestPointAndNormal(ob.mesh, head.position);
            dist = res.distance;
            normal = res.normal;
          }
        }

        if (dist !== undefined && normal !== undefined && dist < 0.3 && normal.length() > 0) {
          const dot = BABYLON.Vector3.Dot(velocity, normal);
          const reflect = velocity.subtract(normal.scale(2 * dot));
          const weight = (0.3 - dist) / 0.3;
          avoidance = avoidance.add(reflect.subtract(velocity).scale(weight));
        }
      });

      velocity = velocity.add(avoidance);

      // 입자 이동
      head.position.addInPlace(velocity.scale(dt * 2));

      // 속도 크기 계산 (색상용)
      const speed = velocity.length();
      const t = Math.min(speed / 4, 1);
      const rCol = t;
      const gCol = t < 0.5 ? t * 2 : 2 - t * 2;
      const bCol = 1 - t;
      mat.emissiveColor = new BABYLON.Color3(rCol, gCol, bCol);
      lines.color = new BABYLON.Color3(rCol, gCol, bCol);

      // trail 업데이트 (circular buffer)
      trailPoints[trailIndex] = head.position.clone();
      trailIndex = (trailIndex + 1) % trailLength;
      p.trailIndex = trailIndex;

      // Babylon.js에 맞게 위치 데이터 갱신
      const orderedPoints = [];
      for (let i = 0; i < trailLength; i++) {
        const idx = (trailIndex + i) % trailLength;
        orderedPoints.push(trailPoints[idx]);
      }

      const positions = [];
      orderedPoints.forEach((p) => {
        positions.push(p.x, p.y, p.z);
      });
      lines.updateVerticesData(BABYLON.VertexBuffer.PositionKind, positions);

      // 화면 밖 리셋
      if (
        head.position.x > 15 ||
        head.position.x < -15 ||
        head.position.y < -10 ||
        head.position.y > 10 ||
        head.position.z < -10 ||
        head.position.z > 10
      ) {
        const x = -12;
        const y = (Math.random() - 0.5) * 10;
        const z = (Math.random() - 0.5) * 10;

        head.position.set(x, y, z);

        // trailPoints 전부 초기 위치로 덮어쓰기
        for (let j = 0; j < trailLength; j++) {
          trailPoints[j] = head.position.clone();
        }

        // 위치 데이터 float 배열로 변환
        const positions = [];
        trailPoints.forEach((p) => {
          positions.push(p.x, p.y, p.z);
        });

        // lines 메쉬 위치 데이터 업데이트 (새로 생성하지 않음)
        lines.updateVerticesData(BABYLON.VertexBuffer.PositionKind, positions);
      }
    });
  });

  return scene;
}
